/* @author MILO-GAO(高振銘)@2020 */ package page2020.anno;import java.lang.reflect.Field;import java.math.BigDecimal;import java.util.Arrays;import java.util.Date;import java.util.List;import javax.persistence.Column;import org.springframework.util.NumberUtils;import page2020.util.EmptyUtil;import page2020.view.bs4.B4col;import page2020.view.bs4.B4ctrl.B4Type;import page2020.view.html5.H5input.Type;public class CtrlItem extends DataItem<CtrlItem> {	private Ctrl2020 anno;	private boolean key = false;	private String type;	private int[] row = null;	private int[] col = null;	private int[] hiding = null;	private int[] required = null;	private int[] disabled = null;	private int[] autofocus = null;	private String pattern;	private int integer;	private int fraction;	private long minimum;	private long maximum;	private int length;	public CtrlItem(Field field, String className, String topClassName) {		super(field, className, topClassName);		Ctrl2020 anno = null;		if (field.isAnnotationPresent(Ctrl2020.class)) {			field.setAccessible(true);			anno = field.getAnnotation(Ctrl2020.class);			super.anno(anno.name(), anno.index(), anno.key(), anno.hidden());		} else {			return;		}		this.anno = anno;		this.key = anno.key();		this.type = anno.type();		this.row = B4col.numbers(anno.row());		this.col = B4col.numbers(anno.col());		this.hiding = this.code(anno.hiding());		this.required = this.code(anno.required());		this.disabled = this.code(anno.disabled());		this.autofocus = this.code(anno.autofocus());		this.pattern = anno.pattern();		this.length = anno.length() >= 0 ? anno.length() : 0;		Class<?> clazz = field.getType();		if (clazz.equals(Byte.class) ||			clazz.equals(Short.class) ||			clazz.equals(Integer.class) ||			clazz.equals(Long.class) ||			clazz.equals(Float.class) ||			clazz.equals(Double.class) ||			clazz.equals(BigDecimal.class)) {			if (Type.number.equals(this.type)) {				this.pattern = Pattern.digit;			} else if (EmptyUtil.is(this.type) || B4Type.group.equals(this.type)) {				this.pattern = Pattern.number;				this.pattern(clazz);			}		}		if (EmptyUtil.is(this.type)) {			if (clazz.equals(Boolean.class)) {				this.type = Type.checkbox;			} else if (clazz.equals(List.class)) {				this.type = B4Type.select;			} else if (clazz.equals(Date.class)) {				this.type = Type.date;			} else {				this.type = Type.text;			}		}		if (clazz.equals(String.class) && this.length == 0) {			if (field.isAnnotationPresent(Column.class)) {				this.length = field.getAnnotation(Column.class).length();			}			if (this.length == 0) {				this.length = 255;			}		}		if (Type.range.equals(this.type)) {			this.pattern = "";		}	}	public boolean isHiding(int code) {		return this.compareCode(code, this.hiding);	}	public boolean isRequired(int code) {		return this.compareCode(code, this.required);	}	public boolean isDisabled(int code) {		return this.compareCode(code, this.disabled);	}	public boolean isAutofocus(int code) {		return this.compareCode(code, this.autofocus);	}	@Override	public String toString() {		return "CtrlItem [key=" + key + ", type=" + type + ", row=" + Arrays.toString(row) + ", col="				+ Arrays.toString(col) + ", hiding=" + Arrays.toString(hiding) + ", required="				+ Arrays.toString(required) + ", disabled=" + Arrays.toString(disabled) + ", autofocus="				+ Arrays.toString(autofocus) + ", pattern=" + pattern + ", integer=" + integer + ", fraction="				+ fraction + ", minimum=" + minimum + ", maximum=" + maximum + ", length=" + length + "]";	}	private void pattern(Class<?> clazz) {		int integer = this.anno.integer();		int fraction = this.anno.fraction();		if (clazz.equals(Byte.class)) {			this.integer = 0;			this.fraction = 0;			this.minimum = Byte.MIN_VALUE;			this.maximum = Byte.MAX_VALUE;		} else if (clazz.equals(Short.class)) {			this.integer = 0;			this.fraction = 0;			this.minimum = Short.MIN_VALUE;			this.maximum = Short.MAX_VALUE;		} else if (clazz.equals(Integer.class)) {			this.integer = (integer > -1) ? integer : 3;			this.fraction = 0;			this.minimum = Integer.MIN_VALUE;			this.maximum = Integer.MAX_VALUE;		} else if (clazz.equals(Long.class)) {			this.integer = (integer > -1) ? integer : 3;			this.fraction = 0;			this.minimum = Long.MIN_VALUE;			this.maximum = Long.MAX_VALUE;		} else if (clazz.equals(Float.class)) {			this.integer = (integer > -1) ? integer : 3;			this.fraction = (fraction > -1) ? fraction : 2;			this.minimum = Long.MIN_VALUE;					this.maximum = Long.MAX_VALUE;		} else if (clazz.equals(Double.class)) {			this.integer = (integer > -1) ? integer : 3;			this.fraction = (fraction > -1) ? fraction : 4;			this.minimum = Long.MIN_VALUE;					this.maximum = Long.MAX_VALUE;		} else if (clazz.equals(BigDecimal.class)) {			this.integer = (integer > -1) ? integer : 3;			this.fraction = (fraction > -1) ? fraction : 6;			this.minimum = Long.MIN_VALUE;					this.maximum = Long.MAX_VALUE;		}	}	private int[] code(String code) {		if (EmptyUtil.not(code)) {			if (code.contains(",")) {				String[] tokens = code.split(",");				int[] numbers = new int[tokens.length];				for (int i=0; i < tokens.length; i++) {					numbers[i] = NumberUtils.parseNumber(tokens[i].trim(), Integer.class).intValue();				}				return numbers;			} else {				return new int[] { NumberUtils.parseNumber(code.trim(), Integer.class).intValue() };			}		}		return null;	}	private boolean compareCode(int code, int[] numbers) {		if (numbers != null) {			for (int i=0; i < numbers.length; i++) {				if (Code.all == numbers[i] || code == numbers[i]) {					return true;				}			}		}		return false;	}	public Ctrl2020 getAnno() {		return anno;	}	public boolean isKey() {		return key;	}	public String getType() {		return type;	}	public int[] getRow() {		return row;	}	public int[] getCol() {		return col;	}	public String getPattern() {		return pattern;	}	public int getInteger() {		return integer;	}	public int getFraction() {		return fraction;	}	public long getMinimum() {		return minimum;	}	public long getMaximum() {		return maximum;	}	public int getLength() {		return length;	}}